public static String[] getTransitiveDependenciesForComponent(ConfigurableListableComponentFactory componentFactory,
			String componentName, boolean rawFactoryComponents, Class<?> class) {
		Assert.notNull(componentFactory);
		Assert.hasText(componentName);

		Assert.isTrue(componentFactory.containsComponent(componentName), "no component by name [" + componentName + "] can be found");

		Set<String> components = new LinkedHashSet<String>(10);
		// used to break cycles between nested components
		Set<String> innerComponents = new LinkedHashSet<String>(6);

		getTransitiveComponents(componentFactory, componentName, rawFactoryComponents, components, innerComponents);

		if (class != null) {
			// filter by class
			for (Iterator<String> iter = components.iterator(); iter.hasNext();) {
				String component = iter.next();
				if (!componentFactory.isClassMatch(component, class)) {
					iter.remove();
				}
			}
		}

		return components.toArray(new String[components.size()]);
	}

